ds = median(diff(s)); % Song time differnce between beats

disp("The Song's Beats Sequence: 122 BPM");
disp(s(1:20));


% Reshape and Organize 
W = 5;  % time for each chunk
M = round(W/ds); % Number of beats per chunk
size = length(s); % Number of total beats

N = floor(size / M); % Number of whole chunks

new_size = M*N; 

s = s(1:new_size); % Discard chunks from the end
s = reshape(s,M,N); % Reshape - each chunk is now colomn

disp("Song Beats - each colomn is one chunk of 5 seconds interval:")
disp(s)

% Create Theoretical cadence
r_nom = 1.1; % Chosen speed up
c = 1/r_nom * s; % Theoretical Cadence
dc = median(diff(c), "all"); % Cadence time differnce between beats

% Add Noise
sigma = 0.04*dc;
e = sigma*randn(new_size,1);
c = reshape(c,new_size,1);
for j = 2:new_size
    c(j) = c(j-1) + dc + e(j);
end

c = reshape(c,M,N);
disp("Cadence - 134 SPM, noisy with std = 5 SPM");
disp(c)


% Mean phase error 
s_c_diff = abs(s-r_nom*c);
avg_error_before = mean(mean(abs(s-r_nom*c)));

disp("Mean Phase Error (in ms):");
disp(round(avg_error_before*1000));

% Calculate r_opt
r_opt = ones(1,N);
for j =1:N
    v = s(:,j)./c(:,j);
    w = c(:,j);
    v_w = [v, w];

    v_w_sorted = sortrows(v_w,1);

    half_point = sum(w)/2;

    v_w_cum=cumsum(v_w_sorted(:,2));

idx_cum = find(v_w_cum > half_point, 1, 'first');

r_opt(j) = v(idx_cum);
end
disp("Optimal speed-up for each chunk:")
disp(r_opt)

% Mean phase error - after L1 minimzation
avg_error_after = mean(mean(abs(s-r_opt.*c)));
disp("Mean Phase Error - After L1 minimization (in ms):")
disp(round(avg_error_after*1000))
diary off
